namespace DiskLens;
public static class DuplicateRegressionTests {
 public static async Task Run(string root,Action<bool,string> check){var fixture=Path.Combine(root,"full-hash-fixture");Directory.CreateDirectory(fixture);var bytes=new byte[131072];File.WriteAllBytes(Path.Combine(fixture,"same-a.bin"),bytes);File.WriteAllBytes(Path.Combine(fixture,"same-b.bin"),bytes);bytes[^1]=1;File.WriteAllBytes(Path.Combine(fixture,"different-tail.bin"),bytes);var store=new Store(Path.Combine(root,"full-hash-store"));var pending=Path.Combine(store.Home,"pending");var scan=await new Scanner().Run(fixture,pending,false,"",new Progress<string>(),CancellationToken.None);store.Commit(scan,pending,20);var rows=await Duplicates.Find(store,scan,"",1,0,new Progress<string>(),CancellationToken.None);check(rows.Count==2&&rows.All(r=>!r.Name.StartsWith("different")),"duplicates verify entire content, including beyond first buffer");var reports=new List<string>();var filtered=await Duplicates.Find(store,scan,"same-*",1,0,new Progress<string>(text=>{}),CancellationToken.None);check(filtered.Count==2,"wildcard-filtered duplicate group still verifies full contents");}
}
